    <!-- Modile Banner Sticky Bar -->
    
    <!-- Toggle "More" popup -->
    <script>
        document.getElementById('moreBtn').addEventListener('click', function () {
            document.getElementById('popup').classList.toggle('open');
        });
        
        const coinBtn = document.getElementById("coinBtn");
        const front = coinBtn.querySelector(".coin-front");
        const back = coinBtn.querySelector(".coin-back");

        let isFlipped = false;
        let isAnimating = false;

        // FRONT CLICK
        front.addEventListener("click", function (e) {
            e.stopPropagation();
            if (isAnimating) return;
            isAnimating = true;
            const url = this.dataset.url;
            coinBtn.classList.add("flip");
            setTimeout(() => {
                window.location.href = url;
            }, 700);
        });


        // BACK CLICK
        back.addEventListener("click", function (e) {
            e.stopPropagation();
            if (isAnimating) return;
            isAnimating = true;
            const url = this.dataset.url;
            coinBtn.classList.remove("flip");
            setTimeout(() => {
                window.location.href = url;
            }, 700);
        });
    </script>
    
    <!-- Scrol Sticy Header -->
    <script>
        const header = document.querySelector('header');
        window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.classList.add('sticky');
        } else {
            header.classList.remove('sticky');
        }
        });
    </script>

    <!--- Phone Notification --->                    
    <script>
        const phonenotification = document.getElementById('phonenotification');
        const notificationsection = document.getElementById('notificationsection');
        phonenotification.addEventListener('click', ()=>{
            notificationsection.classList.toggle('show');
        });
    </script>

<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script>
<script>
    const USER_ID = {{ auth()->id() }};
    
    function updateNotificationCount(count) {
        const badge = document.getElementById('notificationCount');

        if (!badge) return;

        if (count > 0) {
            badge.style.display = 'inline-flex';
            badge.textContent = count;
        } else {
            badge.style.display = 'none';
            badge.textContent = '';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {

        if (window.Echo) {

            window.Echo
                .private('user.{{ auth()->id() }}')
                .listen('.notification.updated', function() {

                    const badge = document.getElementById('notificationCount');

                    if (!badge) return;

                    let count = parseInt(badge.textContent || 0);

                    count++;

                    updateNotificationCount(count);

                });
                
                
        window.Echo.private('notifications.' + USER_ID)
            .listen('.notification.created', (e) => {
        
                console.log('==============================');
                console.log('Notification Received');
                console.log(e);
                console.log('Title:', e.title);
                console.log('Message:', e.message);
                console.log('URL:', e.url);
                console.log('==============================');
        
                $('.notification-count').text(
                    parseInt($('.notification-count').text()) + 1
                );
        
                let html = `
                    <a href="${e.url}" class="dropdown-item notification-item">
                        <i class="fas ${e.icon}"></i>
                        <div>
                            <strong>${e.title}</strong>
                            <p>${e.message}</p>
                            <small>${e.created_at}</small>
                        </div>
                    </a>
                `;
        
                $('.notification-list').prepend(html);
        
            })
            .error((error) => {
                console.error('Notification Channel Error:', error);
            });

        }

    });
</script>